-- LOCAL REHEARSAL BODY (throwaway database; synthetic rows; everything rolls back). Run via rehearse.sh, AFTER the real 0169/0170/0171 SQL.
create temp table results (n serial, label text, pass boolean);
create function pg_temp.chk(l text, c boolean) returns void language sql as $$ insert into results(label, pass) values (l, coalesce(c, false)) $$;
create temp table errs (n serial, msg text);
create function pg_temp.fails(q text) returns boolean language plpgsql as $$ begin execute q; insert into errs(msg) values ('!! NO ERROR: ' || left(q, 90)); return false; exception when others then insert into errs(msg) values (sqlerrm); return true; end $$;

