insert into public.portfolio_internal_reviews (project_file_id,candidate_id,decision,destinations,checks,notes,reviewed_by) select project_file_id,id,'approved','{portfolio}','{"confidentiality":true,"embargo":true,"contractual_restrictions":true,"release_rights":true,"quality":true}','strong frame','00000000-0000-4000-8000-0000000000a3' from public.portfolio_candidates where project_file_id='00000000-0000-4000-8000-0000000a0001';
select pg_temp.chk('eligibility: both stages = eligible for the approved destination only', (select eligible from public.portfolio_use_eligibility('00000000-0000-4000-8000-0000000a0001','portfolio')) and (select internal_reason from public.portfolio_use_eligibility('00000000-0000-4000-8000-0000000a0001','website'))='destination_not_approved');
select pg_temp.chk('eligibility: internal approval without permission is not enough (photo 3)', pg_temp.fails($q$insert into public.portfolio_use_events (project_file_id,destination,action,actor_id) values ('00000000-0000-4000-8000-0000000a0003','portfolio','published','00000000-0000-4000-8000-0000000000a2')$q$));
insert into public.portfolio_use_events (project_file_id,destination,action,reference,actor_id) values ('00000000-0000-4000-8000-0000000a0001','portfolio','published','cms:1','00000000-0000-4000-8000-0000000000a2');
select pg_temp.chk('use: allowed when both stages hold; not flagged', (select count(*) from public.portfolio_uses_needing_review)=0);
insert into public.marketing_permission_records (job_type,job_id,source,decision,supersedes_id,grantor_name,grantor_capacity,recorded_by,method,evidence_summary,note) values ('crew_support_request','00000000-0000-4000-8000-0000000c0001','admin_recorded','withdrawn','00000000-0000-4000-8000-0000000b0004','Synthetic Grantor','client','00000000-0000-4000-8000-0000000000a2','message','withdrawal message received','client asked to stop');
select pg_temp.chk('withdrawal: flags the existing publication for review (nothing is auto-removed)', (select count(*) from public.portfolio_uses_needing_review where project_file_id='00000000-0000-4000-8000-0000000a0001')=1 and (select count(*) from public.portfolio_use_events)=1);
select pg_temp.chk('withdrawal: blocks future use', pg_temp.fails($q$insert into public.portfolio_use_events (project_file_id,destination,action,actor_id) values ('00000000-0000-4000-8000-0000000a0001','portfolio','shared','00000000-0000-4000-8000-0000000000a2')$q$));
insert into public.portfolio_use_events (project_file_id,destination,action,reference,actor_id) values ('00000000-0000-4000-8000-0000000a0001','portfolio','ended','cms:1','00000000-0000-4000-8000-0000000000a2');
select pg_temp.chk('use: ending a use is always allowed and clears the flag', (select count(*) from public.portfolio_uses_needing_review)=0);
insert into public.portfolio_internal_reviews (project_file_id,candidate_id,decision,notes,reviewed_by) select project_file_id,id,'revoked','quality concern','00000000-0000-4000-8000-0000000000a2' from public.portfolio_candidates where project_file_id='00000000-0000-4000-8000-0000000a0001';
select pg_temp.chk('revocation: internal approval can be revoked', (select internal_reason from public.portfolio_use_eligibility('00000000-0000-4000-8000-0000000a0001','portfolio'))='revoked');
select pg_temp.chk('reviews and use events are append-only', pg_temp.fails('update public.portfolio_internal_reviews set notes=''x''') and pg_temp.fails('delete from public.portfolio_use_events'));
select pg_temp.chk('standing: one call covers every photograph and destination, and agrees with the eligibility function', (select count(*) from public.portfolio_standing(array['00000000-0000-4000-8000-0000000a0001','00000000-0000-4000-8000-0000000a0002']::uuid[]))=16 and (select eligible from public.portfolio_standing(array['00000000-0000-4000-8000-0000000a0002']::uuid[]) where destination='portfolio') = (select eligible from public.portfolio_use_eligibility('00000000-0000-4000-8000-0000000a0002','portfolio')));
select pg_temp.chk('RLS: staff read policies exist on every new table', (select count(*) from pg_policies where schemaname='public' and tablename in ('portfolio_candidates','portfolio_collections','portfolio_collection_items','marketing_permission_requests','marketing_permission_records','portfolio_internal_reviews','portfolio_use_events'))>=9);
select pg_temp.chk('RLS: enabled on every new table', (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('portfolio_candidates','portfolio_collections','portfolio_collection_items','marketing_permission_requests','marketing_permission_records','portfolio_internal_reviews','portfolio_use_events') and c.relrowsecurity)=7);

select n, case when pass then 'OK  ' else 'FAIL' end res, label from results order by n;
select 'REJECTION ' || n || ': ' || left(msg, 150) from errs order by n;
select 'SUMMARY ' || count(*) filter (where pass) || ' pass, ' || count(*) filter (where not pass) || ' fail' from results;
